CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL, category_id INTEGER REFERENCES categories(id), image TEXT, available BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS promos (id SERIAL PRIMARY KEY, title TEXT NOT NULL, text TEXT NOT NULL, product_id INTEGER REFERENCES products(id));
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id), shipping JSONB NOT NULL, total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id SERIAL PRIMARY KEY, order_id INTEGER REFERENCES orders(id), product_id INTEGER, product_name TEXT NOT NULL, price_at_purchase INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0));
